-- ============================================================
-- Migration: 20260422100100_projects_extend_status_columns
-- Purpose : Extend projects status to 7 values, add new columns
--           (size, color_mode, deposit_apply_rule, secondary_artist_ids,
--            reference_notes, stalled_at)
-- Tables  : projects
-- Rollback:
--   ALTER TABLE projects DROP COLUMN IF EXISTS stalled_at;
--   ALTER TABLE projects DROP COLUMN IF EXISTS reference_notes;
--   ALTER TABLE projects DROP COLUMN IF EXISTS secondary_artist_ids;
--   ALTER TABLE projects DROP COLUMN IF EXISTS deposit_apply_rule;
--   ALTER TABLE projects DROP COLUMN IF EXISTS color_mode;
--   ALTER TABLE projects DROP COLUMN IF EXISTS size;
--   ALTER TABLE projects DROP CONSTRAINT IF EXISTS chk_projects_status;
--   ALTER TABLE projects ALTER COLUMN status SET DEFAULT 'active';
--   ALTER TABLE projects ADD CONSTRAINT chk_projects_status_legacy
--     CHECK (status IN ('active','completed','on_hold','cancelled'));
--   DROP INDEX IF EXISTS idx_projects_stalled_at;
-- ============================================================

-- ── 1. Drop the old 4-value status check constraint ───────────────────────────
--       The original migration used an inline CHECK; Postgres names it
--       projects_status_check. Drop by name; ignore if already absent.
ALTER TABLE projects
  DROP CONSTRAINT IF EXISTS projects_status_check;

-- ── 2. Add the new 7-value status check constraint ───────────────────────────
ALTER TABLE projects
  ADD CONSTRAINT chk_projects_status
    CHECK (status IN (
      'planning',
      'deposit_paid',
      'active',
      'healing',
      'completed',
      'on_hold',
      'cancelled'
    ));

-- ── 3. Backfill: active rows that are already done → completed ────────────────
UPDATE projects
SET status = 'completed'
WHERE status = 'active'
  AND completed_at IS NOT NULL;

-- Remaining active rows stay 'active' — no change needed.

-- ── 4. Set column default to planning for new rows ────────────────────────────
ALTER TABLE projects
  ALTER COLUMN status SET DEFAULT 'planning';

-- ── 5. Add new columns ────────────────────────────────────────────────────────

-- Size of the piece
ALTER TABLE projects
  ADD COLUMN IF NOT EXISTS size text NULL
    CHECK (size IS NULL OR size IN (
      'small', 'medium', 'large', 'extra_large', 'full_sleeve', 'full_back'
    ));

COMMENT ON COLUMN projects.size IS 'Physical size bucket for the piece';

-- Colour mode
ALTER TABLE projects
  ADD COLUMN IF NOT EXISTS color_mode text NULL
    CHECK (color_mode IS NULL OR color_mode IN ('color', 'black_and_grey', 'both'));

COMMENT ON COLUMN projects.color_mode IS 'Ink colour approach for the project';

-- Deposit application rule
ALTER TABLE projects
  ADD COLUMN IF NOT EXISTS deposit_apply_rule text NOT NULL DEFAULT 'last_session'
    CHECK (deposit_apply_rule IN ('last_session', 'split_evenly', 'manual'));

COMMENT ON COLUMN projects.deposit_apply_rule IS
  'How deposits are credited against sessions: last_session | split_evenly | manual';

-- Secondary artists (collaborations / guest spots)
ALTER TABLE projects
  ADD COLUMN IF NOT EXISTS secondary_artist_ids uuid[] NOT NULL DEFAULT '{}';

COMMENT ON COLUMN projects.secondary_artist_ids IS
  'UUIDs of additional artists on the project (references artists.id)';

-- Free-form reference notes
ALTER TABLE projects
  ADD COLUMN IF NOT EXISTS reference_notes text NULL;

COMMENT ON COLUMN projects.reference_notes IS
  'Client-provided reference notes: style keywords, inspirations, exclusions';

-- Stall timestamp (set by app job when planning + no activity ≥ 45 days)
ALTER TABLE projects
  ADD COLUMN IF NOT EXISTS stalled_at timestamptz NULL;

COMMENT ON COLUMN projects.stalled_at IS
  'Set by background job when project stays in planning with no activity for 45+ days';

-- ── 6. Index for stalled project sweep ────────────────────────────────────────
CREATE INDEX IF NOT EXISTS idx_projects_stalled_at
  ON projects (stalled_at)
  WHERE stalled_at IS NOT NULL;

-- ============================================================
-- Migration: 20260422100400_project_references_extend
-- Purpose : Add source, external_url, flash_design_id to
--           project_references.
--           flash_designs table does NOT exist in this codebase
--           (confirmed by grep of all migrations). flash_design_id
--           is added as a plain uuid with a TODO comment; no FK.
-- Tables  : project_references
-- Rollback:
--   ALTER TABLE project_references DROP COLUMN IF EXISTS flash_design_id;
--   ALTER TABLE project_references DROP COLUMN IF EXISTS external_url;
--   ALTER TABLE project_references DROP COLUMN IF EXISTS source;
-- ============================================================

-- ── 1. source column ──────────────────────────────────────────────────────────
ALTER TABLE project_references
  ADD COLUMN IF NOT EXISTS source text NOT NULL DEFAULT 'upload'
    CHECK (source IN ('upload', 'pinterest', 'instagram', 'behance', 'flash_design'));

COMMENT ON COLUMN project_references.source IS
  'Where the reference image came from: upload | pinterest | instagram | behance | flash_design';

-- ── 2. external_url column ────────────────────────────────────────────────────
ALTER TABLE project_references
  ADD COLUMN IF NOT EXISTS external_url text NULL;

COMMENT ON COLUMN project_references.external_url IS
  'Source URL for pinterest / instagram / behance references';

-- ── 3. flash_design_id column ─────────────────────────────────────────────────
--       TODO: when flash_designs table is created, add:
--         ALTER TABLE project_references
--           ADD CONSTRAINT project_references_flash_design_id_fkey
--             FOREIGN KEY (flash_design_id) REFERENCES flash_designs(id) ON DELETE SET NULL;
--         CREATE INDEX IF NOT EXISTS idx_project_references_flash_design_id
--           ON project_references (flash_design_id) WHERE flash_design_id IS NOT NULL;
ALTER TABLE project_references
  ADD COLUMN IF NOT EXISTS flash_design_id uuid NULL;

COMMENT ON COLUMN project_references.flash_design_id IS
  'References flash_designs.id — FK intentionally omitted (table does not yet exist). Add FK when flash_designs migration is created.';

